INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25401, 'John 11:5', 'John', 11, 5, '&nbsp;اګر چې عيسىٰ د مرتا، او د هغې خور او لعزر سره مينه کوله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25402, 'John 11:6', 'John', 11, 6, '&nbsp;خو چې هغۀ د لعزر د بيمارۍ واورېدل نو هغه دوه ورځې نور هم په هغه ځائ کښې ايسار شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25403, 'John 11:7', 'John', 11, 7, '&nbsp;بيا د دې نه پس عيسىٰ خپلو مريدانو ته وفرمائيل، ”راځئ چې يهوديه ته واپس لاړ شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25404, 'John 11:8', 'John', 11, 8, '&nbsp;مريدانو ورته ووئيل چې، ”اُستاذه، څۀ لږ وخت مخکښې يهوديانو ستا سنګسارول غوښتل، او تۀ بيا هلته ځې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25405, 'John 11:9', 'John', 11, 9, '&nbsp;عيسىٰ جواب ورکړو، ”ولې په ورځ کښې دولس ګينټې رڼا نۀ وى څۀ؟ هر څوک چې د ورځې ګرځى تيندک نۀ خورى ځکه چې هغوئ د دې دُنيا رڼا وينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25406, 'John 11:10', 'John', 11, 10, '&nbsp;خو څوک چې د شپې ګرځى نو تيندک به خورى ځکه چې هغۀ سره رڼا نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25407, 'John 11:11', 'John', 11, 11, '&nbsp;د دې وئيلو نه پس عيسىٰ وفرمائيل چې، ”زمونږ دوست لعزر اودۀ پروت دے خو زۀ ورځم چې راويښ يې کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25408, 'John 11:12', 'John', 11, 12, '&nbsp;مريدانو هغۀ ته ووئيل، ”مالِکه، کۀ چرې هغه اودۀ وى نو هغه به روغ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25409, 'John 11:13', 'John', 11, 13, '&nbsp;عيسىٰ د هغۀ د مرګ خبره کوله خو د هغوئ خيال وو چې ګنې دے د فطرى اودۀ کېدو خبره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25410, 'John 11:14', 'John', 11, 14, '&nbsp;بيا عيسىٰ هغوئ ته صفا وفرمائيل، ”لعزر مړ دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25411, 'John 11:15', 'John', 11, 15, '&nbsp;نو ستاسو دپاره دا ښۀ ده چې زۀ هلته نۀ وم نو چې تاسو ايمان راوړئ. خو راځئ چې هغۀ له ورشُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25412, 'John 11:16', 'John', 11, 16, '&nbsp;بيا توما چې برغونے ورته وائى، هغۀ نورو مريدانو ته ووئيل، ”راځئ چې مونږ هم لاړ شُو چې د هغۀ سره مړۀ شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25413, 'John 11:17', 'John', 11, 17, '&nbsp;کله چې عيسىٰ ورسېدو نو خبر شو چې څلور ورځې مخکښې لعزر دفن شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25414, 'John 11:18', 'John', 11, 18, '&nbsp;بيتِ‌عنياه د يروشلم نه څۀ دوه ميله لرې وه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25415, 'John 11:19', 'John', 11, 19, '&nbsp;او ډېر يهوديان مرتا او مريمې ته د هغوئ د ورور غمرازۍ له راغلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25416, 'John 11:20', 'John', 11, 20, '&nbsp;کله چې مرتا د عيسىٰ د راتلو نه خبر شوه نو هغۀ سره مِلاوېدو له ورغله، خو مريم په کور کښې پاتې شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25417, 'John 11:21', 'John', 11, 21, '&nbsp;مرتا عيسىٰ ته ووئيل، ”مالِکه، کۀ تۀ دلته وے نو زما ورور به مړ شوے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25418, 'John 11:22', 'John', 11, 22, '&nbsp;خو زۀ اوس هم پوهېږم چې کۀ تۀ د خُدائ پاک نه هر څۀ وغواړې نو خُدائ پاک به يې درکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25419, 'John 11:23', 'John', 11, 23, '&nbsp;عيسىٰ هغې ته وفرمائيل چې، ”ستا ورور به بيا راژوندے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25420, 'John 11:24', 'John', 11, 24, '&nbsp;مرتا هغۀ ته ووئيل، ”خو ما ته پته ده چې د قيامت په ورځ به هغه بيا راژوندے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25421, 'John 11:25', 'John', 11, 25, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”زۀ قيامت او ژوندون يم. څوک چې په ما ايمان ساتى کۀ هغه مړ هم شى نو هغه به ژوندے وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25422, 'John 11:26', 'John', 11, 26, '&nbsp;او څوک چې ژوندے دے او په ما ايمان لرى هغه به هيڅکله هم مړ نۀ شى. آيا ستا په دې يقين دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25423, 'John 11:27', 'John', 11, 27, '&nbsp;هغې هغۀ ته ووئيل، ”آو، مالِکه، زما په دې ايمان دے چې تۀ مسيح يې، د خُدائ پاک زوئ، څوک چې دُنيا ته راتلونکے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25424, 'John 11:28', 'John', 11, 28, '&nbsp;کله چې هغې دا ووئيل، نو هغه واپس لاړه او خپله خور مريم يې راوبلله، او په پټه يې ورته ووئيل، ”اُستاذ دلته دے او هغه تا غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25425, 'John 11:29', 'John', 11, 29, '&nbsp;کله چې مريم دا واورېدل نو سمدستى پاڅېده او عيسىٰ له ورغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25426, 'John 11:30', 'John', 11, 30, '&nbsp;خو عيسىٰ لا کلى ته نۀ وو رارسېدلے او لا په هغه ځائ کښې وو چرته چې مرتا هغۀ سره مِلاو شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25427, 'John 11:31', 'John', 11, 31, '&nbsp;کوم يهوديان چې د مريم سره غمرازۍ دپاره کور کښې وُو، نو چې هغوئ وليدل چې هغه زر پاڅېده او بهر لاړه نو هغوئ ورپسې روان شول، ځکه چې هغوئ دا ګڼل چې قبر له روانه ده چې پرې وژاړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25428, 'John 11:32', 'John', 11, 32, '&nbsp;کله چې مريم هغه ځائ له ورغله چرته چې عيسىٰ وو نو د هغۀ په ليدو سره په پښو ورته پرېوتله او هغۀ ته يې ووئيل، ”اے مالِکه، کۀ چرې تۀ دلته وے نو زما ورور به مړ شوے نۀ وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25429, 'John 11:33', 'John', 11, 33, '&nbsp;کله چې عيسىٰ مريم او ورسره يهوديان په ژړا وليدل نو هغۀ يو سوړ اسويلے وکړو او ډېر زهير شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25430, 'John 11:34', 'John', 11, 34, '&nbsp;هغۀ تپوس وکړو چې، ”هغه تاسو کوم ځائ دفن کړے دے؟“ هغوئ جواب ورکړو، ”مالِکه، راشه او وې ګوره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25431, 'John 11:35', 'John', 11, 35, '&nbsp;عيسىٰ په ژړا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25432, 'John 11:36', 'John', 11, 36, '&nbsp;يهوديانو ووئيل چې، ”وګوره د دۀ هغۀ سره څومره مينه وه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25433, 'John 11:37', 'John', 11, 37, '&nbsp;خو ځينو ووئيل چې، ”ولې دې سړى چا چې د هغه ړوند سړى سترګې بينا کړې وې دا نۀ شو کولے چې لعزر يې د مرګ نه بچ کړے وے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25434, 'John 11:38', 'John', 11, 38, '&nbsp;عيسىٰ بيا سوړ اسويلے وکړو، او قبر له راغے. دا يو غار وو چې مخې ته يې ګټه اېښودلے شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25435, 'John 11:39', 'John', 11, 39, '&nbsp;عيسىٰ وفرمائيل، ”دا ګټه لرې کړئ.“ مرتا، د مړ سړى خور، هغۀ ته ووئيل، ”مالِکه، اوس خو به يې بوئ کړے وى ځکه چې د دۀ د مرګ خو څلور ورځې شوې دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25436, 'John 11:40', 'John', 11, 40, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”ولې ما تاسو ته دا نۀ وُو وئيلى څۀ، چې کۀ چرې تاسو ايمان لرئ نو تاسو به د خُدائ پاک لوئى ووينئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25437, 'John 11:41', 'John', 11, 41, '&nbsp;نو هغوئ ګټه لرې کړله. بيا عيسىٰ پورته وکتل او وې فرمائيل، ”پلاره، زۀ ستا شُکر کوم چې تا زما دُعا واورېدله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25438, 'John 11:42', 'John', 11, 42, '&nbsp;ما ته پته ده چې تۀ همېشه زما اورې، خو ما د دې حاضرو خلقو دپاره سوال وکړو نو چې د دوئ دا باور وشى چې زۀ تا رالېږلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25439, 'John 11:43', 'John', 11, 43, '&nbsp;بيا کله چې هغۀ دا وفرمائيل نو هغۀ په اوچت آواز چغه کړه، ”لعزره، بهر راوځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25440, 'John 11:44', 'John', 11, 44, '&nbsp;نو مړ سړے بهر راووتو، د هغۀ لاس او پښې د کتان په کفن کښې تړلے شوى وُو او مخ يې په ټوکى کښې انغښتے شوے وو. عيسىٰ هغوئ ته وفرمائيل، ”د دۀ نه کفن لرې کړئ او پرې يې ږدئ چې ځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25441, 'John 11:45', 'John', 11, 45, '&nbsp;ډېر خلق چې د مريم سره قبر له راغلى وُو هغوئ چې هغه څۀ وليدل کوم چې عيسىٰ وکړل نو په هغۀ يې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25442, 'John 11:46', 'John', 11, 46, '&nbsp;خو په هغوئ کښې ځينې فريسيانو له ورغلل او هغه څۀ يې ورته ووئيل څۀ چې عيسىٰ کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25443, 'John 11:47', 'John', 11, 47, '&nbsp;نو مشرانو اِمامانو او فريسيانو يوه جرګه راوبلله او وې وئيل چې، ”مونږ ته څۀ کول په کار دى؟ ځکه چې دا سړے خو ډيرې معجزې ښکاره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25444, 'John 11:48', 'John', 11, 48, '&nbsp;کۀ مونږ دے دغه شان آزاد پرېږدو نو ټول خلق به په دۀ ايمان راوړى، او بيا به روميان راشى او زمونږ ټول قوم او د خُدائ کور به تباه کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25445, 'John 11:49', 'John', 11, 49, '&nbsp;خو په دوئ کښې يو تن چې نوم يې کائفس وو څوک چې په دغه کال د ټولو نه مشر اِمام وو، هغوئ ته ووئيل، ”تاسو په هيڅ نۀ پوهېږئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25446, 'John 11:50', 'John', 11, 50, '&nbsp;تاسو په دې نۀ پوهېږئ چې ستاسو دپاره دا غوره ده چې د قوم دپاره دې يو سړے مړ کړے شى، نه چې ټول قوم تباه او برباد شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25447, 'John 11:51', 'John', 11, 51, '&nbsp;هغۀ دا د خپله ځانه ونۀ وئيل، بلکې د هغه کال د مشر اِمام په حيثيت يې دا پېشګوئې وکړله چې عيسىٰ به د قوم دپاره قربان شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25448, 'John 11:52', 'John', 11, 52, '&nbsp;او نۀ صرف د قوم دپاره، بلکې د دې دپاره چې په ټوله دُنيا کښې د خُدائ پاک خوارۀ وارۀ بچى رايوځائ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25449, 'John 11:53', 'John', 11, 53, '&nbsp;نو د هم هغه ورځې نه پس هغوئ د هغۀ د مرګ منصوبه جوړه کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25450, 'John 11:54', 'John', 11, 54, '&nbsp;نو په دې وجه عيسىٰ نور د يهوديانو په مينځ کښې آزاد نۀ ګرځېدو بلکې د هغه ځائ نه يو کلى ته لاړو چې نوم يې اِفرائيم وو چې د صحرا سره نزدې مُلک کښې وو او هغه هلته د خپلو مريدانو سره پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25451, 'John 11:55', 'John', 11, 55, '&nbsp;اوس د يهوديانو د فسح اختر رانزدې وو او ډېر خلق د کلى نه يروشلم ته د فسح د اختر نه مخکښې لاړل چې خپل ځانونه مقدس کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25452, 'John 11:56', 'John', 11, 56, '&nbsp;هغوئ عيسىٰ لټولو او کله چې هغوئ د خُدائ په کور کښې ودرېدل نو د يو بل نه يې تپوس کولو، ”څۀ مو خيال دے؟ ولې هغه به اختر له رانۀ شى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25453, 'John 11:57', 'John', 11, 57, '&nbsp;په دې وخت کښې مشرانو اِمامانو او فريسيانو دا حُکم ورکړے وو چې چا د عيسىٰ پته ولګوله چې چرته دے نو دوئ دې پرې خبر کړى چې هغه ګرفتار کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25454, 'John 12:1', 'John', 12, 1, '&nbsp;د فسح د اختر نه شپږ ورځې مخکښې عيسىٰ بيتِ‌عنياه ته راغے چرته چې د لعزر کور وو، څوک چې هغۀ د مړو نه بيا ژوندے کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25455, 'John 12:2', 'John', 12, 2, '&nbsp;هلته هغوئ هغۀ له د ماښام مېلمستيا وکړه چې مرتا په کښې خِدمت کولو او لعزر هم د عيسىٰ سره په نورو مېلمنو کښې په دسترخوان ناست وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25456, 'John 12:3', 'John', 12, 3, '&nbsp;بيا مريم ښۀ قيمتى عطر چې نيم سېر قدرې وُو او د خالص خوشبوداره مرهمو نه جوړ وو راوړل، او د عيسىٰ په پښو يې واچول او هغه يې بيا په خپلو وېښتو وچې کړې او ټول کور د دې عطرو د خوشبويۍ نه ډک شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25457, 'John 12:4', 'John', 12, 4, '&nbsp;خو په دې يهوداه اِسکريوتى، چې د عيسىٰ يو مريد وو چې لږ وروستو د هغۀ مُخبر کېدونکے وو، ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25458, 'John 12:5', 'John', 12, 5, '&nbsp;”دا عطر په درې سوه ديناره ولې خرڅ نۀ کړے شو چې پېسې يې خوار غريب له ورکړے شوے وے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25459, 'John 12:6', 'John', 12, 6, '&nbsp;هغۀ دا خبره په دې ونۀ کړه چې ګنې هغه د خوارانو غمخور وو، خو ځکه چې هغه په خپله غل وو. هغۀ به د هغه پېسو نه هم پټولې کومې به چې د چندې په تيلۍ کښې جمع کېدې او د هغۀ په اختيار کښې به وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25460, 'John 12:7', 'John', 12, 7, '&nbsp;عيسىٰ وفرمائيل چې، ”هغه خپلې خوښې ته پرېږدئ. هغې دا عطر واخستل چې زما د ښخولو د ورځې دپاره يې وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25461, 'John 12:8', 'John', 12, 8, '&nbsp;ځکه چې غريبانان خو به تل تاسو سره وى خو زۀ به درسره تل نۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25462, 'John 12:9', 'John', 12, 9, '&nbsp;کله چې د يهوديانو هغه لويه ګڼه خبر شوه چې هغه هلته دے، هغوئ نۀ يواځې دې له راتلل چې عيسىٰ ووينى خو د لعزر د کتلو دپاره هم څوک چې هغۀ د مړو نه بيا راژوندے کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25463, 'John 12:10', 'John', 12, 10, '&nbsp;نو مشرانو اِمامانو دا منصوبه جوړه کړه چې لعزر هم مړ کړئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25464, 'John 12:11', 'John', 12, 11, '&nbsp;ځکه چې د هغۀ په وجه ډېر يهوديان عيسىٰ له ورتلل او په هغۀ يې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25465, 'John 12:12', 'John', 12, 12, '&nbsp;په بله ورځ ګڼ خلق چې اختر له راغلى وُو چې د دې نه خبر شول چې عيسىٰ هم يروشلم ته راروان دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25466, 'John 12:13', 'John', 12, 13, '&nbsp;نو هغوئ د کجورې څانګې واخستلې او د هغۀ استقبال له ورووتل او دا نعرې يې وهلې، ”اُمبارکى. مبارک دے هغه څوک چې د مالِک خُدائ په نوم راځى، د بنى اِسرائيلو بادشاه دې مبارک وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25467, 'John 12:14', 'John', 12, 14, '&nbsp;او عيسىٰ يو کوچاڼے وموندلو او په هغې سور شو، لکه څنګه چې په صحيفو کښې ليکلى دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25468, 'John 12:15', 'John', 12, 15, '&nbsp;”اے د صيون لورې. مۀ يرېږه. وګوره، ستا بادشاه په کوچاڼى سور راروان دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25469, 'John 12:16', 'John', 12, 16, '&nbsp;هغه وخت خو د عيسىٰ مريدان په دې پوهه نۀ شول، خو کله چې عيسىٰ خپلې لويئ ته ورسېدلو نو هغوئ ته بيا ورياد شول چې دا خو د هغۀ په حقله ليکلے شوى وُو او هم دغه شان د هغۀ سره وشول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25470, 'John 12:17', 'John', 12, 17, '&nbsp;نو کوم خلق چې د هغۀ سره وُو کله چې عيسىٰ لعزر ته د قبر نه د راوتلو آواز وکړو او د مړو نه يې بيا ژوندے کړو، نو هغوئ د هغې ګواهى جارى ساتله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25471, 'John 12:18', 'John', 12, 18, '&nbsp;هم دغه وجه وه چې ډېر خلق د هغۀ سره مِلاوېدو له ورغلل، ځکه چې هغوئ اورېدلى وُو چې هم هغۀ دا معجزه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25472, 'John 12:19', 'John', 12, 19, '&nbsp;بيا فريسيانو يو بل ته ووئيل، ”تاسو ګورئ چې مونږ هيڅ نۀ شُو کولے، وګورئ، ټوله دُنيا په هغۀ پسې روانه ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25473, 'John 12:20', 'John', 12, 20, '&nbsp;يو څو يونانيان په اختر کښې د عبادت دپاره تلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25474, 'John 12:21', 'John', 12, 21, '&nbsp;هغوئ فيليپوس له راغلل څوک چې د بيتِ‌صيدا د ګليل اوسېدونکے وو، او هغۀ ته يې ووئيل، ”صاحبه، مونږ غواړو چې عيسىٰ سره مِلاو شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25475, 'John 12:22', 'John', 12, 22, '&nbsp;فيليپوس لاړو او اندرياس ته يې ووئيل، بيا هغوئ دواړه لاړل او عيسىٰ يې خبر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25476, 'John 12:23', 'John', 12, 23, '&nbsp;عيسىٰ هغوئ ته جواب ورکړو، ”هغه وخت راغلو چې اِبن آدم خپله لوئى ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25477, 'John 12:24', 'John', 12, 24, '&nbsp;زۀ تاسو ته رښتيا وايم ترڅو چې د غنمو دانه په زمکه کښې ونۀ غورزيږى او په خاوره کښې ښخه او مړه نۀ شى تر هغې به دا صرف يوه دانه وى. خو کله چې دا په خاورو کښې ښخه شى نو دا ډېره مېوه پېدا کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25478, 'John 12:25', 'John', 12, 25, '&nbsp;هغه څوک چې د خپل ژوند سره مينه کوى هغه به يې بائيلى، او څوک چې په دُنيا کښې د خپل ژوند نه نفرت کوى، هغه به يې د تل ژوندون دپاره وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25479, 'John 12:26', 'John', 12, 26, '&nbsp;کۀ څوک زما خِدمت کوى هغه دې ما پسې راځى، او چرته چې زۀ يم هلته به زما خادِم هم وى. هر څوک چې زما خِدمت کوى، هغۀ له به زما پلار عزت ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25480, 'John 12:27', 'John', 12, 27, '&nbsp;اوس زما زړۀ پرېشانه دے او زۀ څۀ ووايم؟ چې اے پلاره، ما د دې وخت نه بچ کړه؟ خو، هم دا وجه ده چې زۀ دې وخت له راغلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25481, 'John 12:28', 'John', 12, 28, '&nbsp;اے پلاره، خپل نوم ته جلال ورکړه.“ بيا د آسمان نه يو آواز راغلو، ”ما خپل نوم ته جلال ورکړے دے او زۀ به بيا هم جلال ورکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25482, 'John 12:29', 'John', 12, 29, '&nbsp;کومه ګڼه چې هلته ولاړه وه هغوئ دا واورېدل او وئ وئيل چې دا د تندر آواز وو خو نورو ووئيل چې، ”فرښتې هغۀ سره خبرې وکړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25483, 'John 12:30', 'John', 12, 30, '&nbsp;عيسىٰ وفرمائيل چې، ”دا آواز زما د ګټې دپاره نه، خو ستاسو دپاره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25484, 'John 12:31', 'John', 12, 31, '&nbsp;اوس د دې دُنيا د عدالت وخت دے او د دې دُنيا سردار يعنې شېطان به اوس بهر وويستلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25485, 'John 12:32', 'John', 12, 32, '&nbsp;او کله چې زۀ د زمکې نه وخېژولے شم نو زۀ به ټول خلق خپل ځان ته راکاږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25486, 'John 12:33', 'John', 12, 33, '&nbsp;عيسىٰ دې خبرې ته اِشاره وکړه چې هغه به په کوم مرګ مرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25487, 'John 12:34', 'John', 12, 34, '&nbsp;ګڼې جواب ورکړو چې، ”زمونږ شريعت دا وائى چې مسيح به تل تر تله وى، نو بيا تۀ څنګه وائې چې اِبن آدم به ضرور په سولۍ وخېژولے شى؟ دا اِبن آدم دے څوک؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25488, 'John 12:35', 'John', 12, 35, '&nbsp;عيسىٰ هغوئ له جواب ورکړو، ”رڼا لږ وخت دپاره تاسو سره ده. ترڅو چې رڼا تاسو سره ده وګرځئ، هسې نه چې تيارۀ مو راګېر کړى. څوک چې په تيارۀ کښې ګرځى، هغۀ ته پته نۀ وى چې چرته روان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25489, 'John 12:36', 'John', 12, 36, '&nbsp;ترڅو چې رڼا تاسو سره ده، په رڼا يقين کوئ نو چې تاسو د رڼا زامن شئ.“ د يهوديانو بې‌ايمانى د دې خبرو نه پس عيسىٰ د هغوئ نه لاړو او پټ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25490, 'John 12:37', 'John', 12, 37, '&nbsp;اګر کۀ عيسىٰ ډيرې معجزې د هغوئ په موجودګۍ کښې وکړې، خو هغوئ په هغۀ باندې ايمان رانۀ وړو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25491, 'John 12:38', 'John', 12, 38, '&nbsp;چې د يشعياه نبى دا خبره پوره شى چې فرمائيلى يې وُو، ”اے مالِکه، زمونږ په پېغام باندې چا يقين کړے دے؟ مالِک خُدائ خپل قوت په چا ظاهر کړے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25492, 'John 12:39', 'John', 12, 39, '&nbsp;په دې وجه هغوئ ايمان راوړلے نۀ شو، ولې چې يشعياه نبى دا هم وفرمائيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25493, 'John 12:40', 'John', 12, 40, '&nbsp;”هغۀ د هغوئ سترګې ړندې کړې دى او زړونه يې ورله سخت کړى دى، نو چې هغوئ په خپلو سترګو ونۀ وينى او په خپلو زړونو کښې پرې پوهه نۀ شى او د رغېدو دپاره ما ته راونۀ ګرځى او زۀ يې روغ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25494, 'John 12:41', 'John', 12, 41, '&nbsp;يشعياه دا خبرې ځکه وکړې چې هغۀ د عيسىٰ لوئى وليده او د هغۀ په حق کښې يې خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25495, 'John 12:42', 'John', 12, 42, '&nbsp;خو سره د دې په هغوئ کښې ډېرو يهودى مشرانو هم په هغۀ ايمان راوړو، خو د فريسيانو په وجه يې د دې اِقرار نۀ کولو، او د دې يرې چې هغوئ به د عبادتخانې نه بهر کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25496, 'John 12:43', 'John', 12, 43, '&nbsp;ځکه چې هغوئ د خُدائ پاک نه د عزت په نسبت د انسان نه عزت حاصلول زيات خوښول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25497, 'John 12:44', 'John', 12, 44, '&nbsp;نو عيسىٰ په اوچت آواز وفرمائيل، ”کۀ څوک په ما ايمان راوړى نو هغه نۀ يواځې دا چې په ما ايمان راوړى بلکې په هغه چا هم چې زۀ يې رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25498, 'John 12:45', 'John', 12, 45, '&nbsp;او څوک چې ما وينى هغه، هغه څوک وينى چې زۀ يې رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25499, 'John 12:46', 'John', 12, 46, '&nbsp;زۀ دُنيا ته لکه د رڼا په شان راغلے يم د دې دپاره چې څوک په ما ايمان راوړى هغه به په تيارۀ کښې پاتې نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25500, 'John 12:47', 'John', 12, 47, '&nbsp;زۀ د هغه چا عدالت نۀ کوم څوک چې زما کلام اورى او تابعدارى يې نۀ کوى ځکه چې زۀ د دې دپاره نۀ يم راغلے چې د دُنيا عدالت وکړم بلکې د دُنيا د بچ کولو دپاره راغلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');